  HEGEL_ZONE_RULE_DAY_JULIAN(0),

  /// `n`: day `day` of the year in `[0, 365]`, counting February 29.
  HEGEL_ZONE_RULE_DAY_ZERO_BASED(1),

  /// `Mm.w.d`: weekday `weekday` (0 is Sunday) of week `week` (1 to 5, 5
  /// meaning the last) of month `month`.
  HEGEL_ZONE_RULE_DAY_MONTH_WEEK_DAY(2);

  final int value;
  const hegel_zone_rule_day_t(this.value);

  static hegel_zone_rule_day_t fromValue(int value) => switch (value) {
    0 => HEGEL_ZONE_RULE_DAY_JULIAN,
    1 => HEGEL_ZONE_RULE_DAY_ZERO_BASED,
    2 => HEGEL_ZONE_RULE_DAY_MONTH_WEEK_DAY,
    _ => throw ArgumentError('Unknown value for hegel_zone_rule_day_t: $value'),
  };
}

final class hegel_zone_source_t extends ffi.Opaque {}

/// An explicit transition: from `instant` (Unix seconds) on, `local_type`
/// is in force.
final class hegel_zone_transition_t extends ffi.Struct {
  @ffi.Int64()
  external int instant;

  external hegel_zone_type_t local_type;
}

/// A local time type: an offset, its DST flag and its abbreviation.
final class hegel_zone_type_t extends ffi.Struct {
  /// Seconds east of UT, less than two days in magnitude.
  @ffi.Int32()
  external int utoff;

  /// Informational: reported by `hegel_timezone_offset_at`, never used
  /// to classify.
  @ffi.Bool()
  external bool is_dst;

  /// Such as `"EST"`; no NUL bytes.
  external hegel_string_t abbreviation;
}

/// A drawn zoned datetime: the wall-clock time `civil` in the zone the
/// draw reports or was given, resolved as `hegel_timezone_resolve_in`
/// resolves it against the zone source drawn from.
final class hegel_zoned_datetime_t extends ffi.Struct {
  external hegel_datetime_t civil;

  /// The offset in force at `timestamp`; 0 when not `offset_known`.
  @ffi.Int32()
  external int offset_seconds;

  /// False for `Etc/Unknown` and for an opaque zone.
  @ffi.Bool()
  external bool offset_known;

  /// Which instant of a repeated wall time the value means (the later
  /// when set); false for a unique or skipped wall time.
  @ffi.Bool()
  external bool fold;

  /// A `hegel_timezone_kind_t`, 32 bits wide.
  @ffi.UnsignedInt()
  external int kindAsInt;

  hegel_timezone_kind_t get kind => hegel_timezone_kind_t.fromValue(kindAsInt);
  set kind(hegel_timezone_kind_t value) => kindAsInt = value.value;

  /// For a gap or fold, the offsets before and after the transition;
  /// both `offset_seconds` otherwise.
  @ffi.Int32()
  external int offset_before;

  @ffi.Int32()
  external int offset_after;

  /// The resolved instant: the unique one, the one `fold` picks, or for
  /// a gap the wall time read with `offset_before`.
  external hegel_timestamp_t timestamp;
}

final class hegel_zoned_spec_t extends ffi.Opaque {}
